from repo import total_cents, invoice

def test_repro():
    # If prices are floats representing cents
    prices = [0.1, 0.2]
    print(f"prices: {prices}")
    print(f"total_cents(prices): {total_cents(prices)}")
    assert total_cents(prices) == 0.3

if __name__ == "__main__":
    try:
        test_repro()
        print("Reproduction test passed")
    except AssertionError as e:
        print(f"Reproduction test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

